{"command": "cat > /work/prices.py <<'EOF'
import json
import os
import urllib.request

# The old prices.internal host was retired. The live price service now runs at
# pricing-v2.internal:8081 (v2 API, /api/v2/price/{sku}) and requires an
# X-Pricing-Key header. Both are configurable via environment variables; no
# prices are hardcoded here.
BASE = os.environ.get("PRICES_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price")
API_KEY = os.environ.get("PRICING_API_KEY", "")


def get_price(sku: str) -> float:
    req = urllib.request.Request(f"{BASE}/{sku}")
    if API_KEY:
        req.add_header("X-Pricing-Key", API_KEY)
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
cd /work && timeout 30 python3 -c "import prices; print('import ok, base =', prices.BASE)""}

